<?php
$q=trim($_GET['q']??'');$search='';$params=[$currentSemesterId];if($q!==''){$search=' AND (u.full_name LIKE ? OR s.matric_number LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}
$project=safeRun($pdo,"SELECT sub.id,sub.file_name,sub.uploaded_at,sub.status,u.full_name,s.matric_number,s.programme_type,sc.name item_name,'Project Submission' item_type FROM submissions sub JOIN students s ON s.id=sub.student_id JOIN users u ON u.id=s.user_id JOIN submission_categories sc ON sc.id=sub.category_id WHERE sub.semester_id=? $search AND sub.id=(SELECT MAX(x.id) FROM submissions x WHERE x.student_id=sub.student_id AND x.category_id=sub.category_id AND x.semester_id=sub.semester_id)",$params)->fetchAll();
$params2=[$currentSemesterId];if($q!==''){$params2[]='%'.$q.'%';$params2[]='%'.$q.'%';}$progress=safeRun($pdo,"SELECT ps.id,ps.file_name,ps.submitted_at uploaded_at,'submitted' status,u.full_name,s.matric_number,pf.programme_type,pf.title item_name,'Progress Form' item_type FROM progress_submissions ps JOIN progress_forms pf ON pf.id=ps.progress_form_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE pf.semester_id=? $search",$params2)->fetchAll();$rows=array_merge($project,$progress);usort($rows,fn($a,$b)=>strcmp($b['uploaded_at'],$a['uploaded_at']));
?>
<div class="card-fy mb-3"><div class="d-flex justify-content-between align-items-end gap-3 flex-wrap"><div><div class="section-title mb-1">Latest Student Submissions</div><p class="small text-muted mb-0">Only the latest file per project category plus submitted progress forms.</p></div><form method="get" class="d-flex gap-2"><input type="hidden" name="view" value="submissions"><input name="q" class="form-control-fy" value="<?= e($q) ?>" placeholder="Search name or matric"><button class="btn-fy-orange">Search</button></form></div></div>
<div class="card-fy"><div class="table-responsive"><table class="table-fy"><thead><tr><th>Student</th><th>Type</th><th>Category / Form</th><th>Programme</th><th>Status</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['matric_number']) ?></div></td><td><?= e($r['item_type']) ?></td><td><?= e($r['item_name']) ?><div class="small text-muted"><?= e($r['file_name']) ?></div></td><td><?= e(programmeTypeLabel($r['programme_type'])) ?></td><td><span class="badge-fy badge-<?= statusBadgeColor($r['status']) ?>"><?= e(submissionStatusLabel($r['status'])) ?></span></td><td><?= timeAgo($r['uploaded_at']) ?></td><td><a target="_blank" class="btn-fy-outline btn-sm" href="<?= e(secureFileUrl((int)$r['id'],$r['item_type']==='Progress Form'?'progress_submission':'submission')) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="text-center text-muted py-5">No matching submissions.</td></tr><?php endif; ?></tbody></table></div></div>
